  AwakerTalent_122607_TalentDesc_1 = {
    Text = "·Cada 2 veces que juegues \"golpear\", Mouchette realiza un seguimiento, infligiendo daño aleatorio equivalente al 30% del ataque de Mouchette, considerado como \"golpe\", con un máximo de 4 activaciones por turno."
  },
  AwakerTalent_122607_TalentName_1 = {
    Text = "Encuentro dramático"
  },
  AwakerTalent_125362_TalentDesc_1 = {
    Text = "Este talento solo es efectivo en las etapas de \"Reino Astral\".\nEl CON, ATQ y DEF de este Despertado +[Arg1]%, y obtiene [Arg2] Llave Plateada en su primer Despertar.\nEl efecto de Activación de Veneno de todos los Despertados +[Arg3]%. \nCada acumulación de \"Ebrio\" reduce adicionalmente el daño infligido por los enemigos \"Humanoide\" en un 1%, y cuando se elimina \"Ebrio\", cada acumulación inflige Daño Fijo equivalente al 1% del PV Max del objetivo a los enemigos \"Humanoide\"."
  },
