  AwakerTalent_127223_TalentDesc_1 = {
    Text = "Cuando Arachne está en el equipo, el Reino Ultra se reteje en Singularidad: Ultra.\nLanzadera Dimensional: Después de jugar la primera Tarjeta de comando cada turno, una Copia Oblivion básica de ella se colocará en el Espacio Hiperspacial y recibirá 25 Acumulaciones de Faro de Singularidad. Esto no puede activarse durante los Turnos Ultra. Si una carta activa la Lanzadera Dimensional, también se beneficia de los efectos del Faro de Singularidad.\nFaro de Singularidad: Por cada Acumulación, el Daño Final de una carta, la ganancia de Fuerza y daño de tentáculos Fijos, el Veneno Fijo y el Contador Fijo aumentan cada uno un +2%; el Escudo del personaje Final, la Recuperación de PV y STR▼ aumentan cada uno un +1%. Este efecto se elimina cuando la carta es jugada. Las cartas con este efecto no pueden activar la Lanzadera Dimensional.\nEspacio Hiperspacial: Cuando está lleno, iniciar el Turno Ultra no termina el turno ni inicia uno nuevo; descarta todas las cartas que no sean Retener, resuelve sus efectos Oblivion, extrae todas las cartas del Espacio Hiperspacial y establece la Aritmética en 5. El turno actual continúa como un Turno Ultra.\nAniquilación de Singularidad: Extrae la carta más a la izquierda del Espacio Hiperspacial y llévala a la mano. Tiempo de reutilización de 3 turnos.\nAl inicio de la investigación, obtén +50% de Amplificación de Daño y 15 Acumulaciones de Prisma de Singularidad.\nPrisma de Singularidad: Los efectos de todas las Tarjetas de comando aumentan como si tuvieran esta cantidad de Acumulaciones de Faro de Singularidad.\nUltra Dominio: Por cada 1 punto de Maestría del Reino, las Acumulaciones de Faro de Singularidad del Prisma de Singularidad y la Lanzadera Dimensional aumentan en un 0,05%.\nUltra Puro: Si el equipo está compuesto únicamente por Despertados Ultra o del Caos, el efecto de Ultra Dominio y la Amplificación de Daño del Reino se duplican."
  },
  AwakerTalent_127223_TalentName_1 = {
    Text = "Hilos del Destino"
  },
  AwakerTalent_130395_TalentDesc_1 = {
