  AwakerTalent_130398_TalentDesc_1 = {
    Text = "Este talento solo es efectivo en las fases del \"Capítulo de las Estrellas\".\nEl CON, ATQ y DEF de este Cuerpo Despertado +[Arg1]%, y obtiene [Arg2] Keyflare tras Activar por primera vez.\nEl Cuerpo Despertado seleccionado por la \"Canción de Saya\" obtiene [Arg3] Acumulaciones de \"Fiesta de Propagación\", y el siguiente Posse se activa 2 veces.\nSaya inflige +[Arg4]% de Corrosión adicional a los enemigos de \"Carne y sangre\"."
  },
