    Text = "·Este Talento solo tiene efecto en los niveles de \"Capítulo Estelar\".\n·El CON, ataque y Defensa del Despertado aumentan un [Arg1]%, y tras Activar Gnosis por primera vez, el Despertado obtiene [Arg2] puntos de Llave Plateada.\n·\"Sombra Salvaje Sin Límites\" causa el Efecto STR▼ y aumenta el multiplicador de fuerza obtenido en [Arg3]%; cada vez que surte Efecto, \"Punta de Lanza Manchada\" recibe un [Arg4]% adicional de bonificación de fuerza, con un límite máximo del 1200%."
  },
