  AwakerTalent_141303_TalentDesc_1 = {
    Text = "·Este talento solo es efectivo en las misiones del \"Capítulo de las Estrellas\". \n·La CON, ATQ y Defensa de este Despertado aumentan un [Arg1]%, y después de jugar por primera vez una carta de Despertar, obtiene [Arg2] puntos de Llave Plateada.\n·El Daño Fijo que \"Pontos\" inflige a los \"Parientes del Éxtasis\" aumenta un [Arg3]%.\n·\"Cacería Implacable\" obtiene un Daño de tentáculos igual al [Arg4]% del ATQ por cada 10 puntos de Aliemus consumidos. Cuando \"Devastación Gaunt\" inflige Daño, también reduce temporalmente la FUE del objetivo en una cantidad igual al [Arg5]% de la DEF."
  },
