  AwakerTalent_143615_TalentDesc_1 = {
    Text = "Cuando este personaje está en el equipo, el Reino Aequor se transforma en el Reino \"Bentos: Aequor\".\n\nEl Daño de tentáculos base cambia al 5% de los PV Max del equipo.\n\nAmplificación de Daño del equipo +50% al comenzar la exploración (Efecto duplicado si el equipo está compuesto íntegramente por Cuerpos Despertados de Aequor y del Caos, aunque no se obtendrán Tentáculos iniciales adicionales).\nEl efecto de Asamblea de tentáculos se elimina.\nLa Postura de tentáculo cambia a \"Bentos: Postura de tentáculo\".\n\n\"Bentos: Mar tranquilo\": Genera inmediatamente un Blindaje equivalente al 25% de los PV Max, y los Tentáculos dejarán de atacar al final del turno; tiempo de reutilización de 3 turnos.\n\"Bentos: Mar embravecido\": El Daño de tentáculos × 125% durante el turno; tras infligir Daño Activo, 1 Tentáculo ataca; se pierde 1 Tentáculo al final del turno; tiempo de reutilización de 3 turnos.\nLa Maestría del Reino se contabiliza como \"Dominio del Mar Profundo: Bentos\". Cada punto proporciona: Generación de Blindaje de la Postura Mar tranquilo +0,025% de PV Max. Daño de tentáculos de la Postura Mar embravecido +0,025%.\nEl efecto de \"Bentos: Maestría del Reino\" se duplica si el equipo está compuesto íntegramente por Cuerpos Despertados de Aequor y del Caos."
  },
  AwakerTalent_143615_TalentName_1 = {
    Text = "Lugar de eterna oscuridad"
  },
