  AwakerTalent_145381_TalentDesc_1 = {
    Text = "·Este Talento solo surte efecto en los Niveles del \"Capítulo de las Estrellas\".\n·El CON, el Ataque y la DEF de este Cuerpo Despertado aumentan en [Arg1]%, y después de que este Cuerpo Despertado juegue Despertar por primera vez, obtiene [Arg2] Keyflare.\n·\"Espada Cortafronteras\" disfruta de una Bonificación de Fortaleza adicional del [Arg3]%. Tras eliminar a un enemigo, obtén [Arg4] Marcas Negras, que disfrutan de la Bonificación de Recompensa de Sello Negro de Lotan: Cetarconte. Surte efecto hasta una vez por batalla."
  },
