  AwakerTalent_145718_TalentDesc_1 = {
    Text = "Cuando Caraboo está en el equipo, el Reino de Carne y sangre muta en Carne de cría.\n\nFusión Embrionaria: La Fusión Embrionaria obtenida por turno aumenta a 50~100, escalando con el PV perdido. El límite de Fusión Embrionaria aumenta de 100 a 200. Al alcanzar el límite, añade 1 \"Embrión Propágulo\" a la mano.\n\nEmbrión Propágulo: Jugar esta carta ya no otorga Probabilidad de Crítico. Devorar ya no otorga Blindaje ni STR temporal. La primera vez que cada Cuerpo Despertado consume un \"Embrión Propágulo\" cada turno, obtiene 40 Acumulaciones de \"Fiesta de Propagación\": Cada acumulación mejora los siguientes efectos Finales del próximo Exaltar de ese Cuerpo Despertado en este turno en un 1%: Daño Final, Blindaje Fijo, Recuperación de PV Fija, Fortaleza Fija/STR▼, Bonificación de daño de tentáculos, Veneno Fijo y Contrataque Fijo.\n\nHorno Carmesí: La acumulación automática En el inicio del turno cambia al 10% del PV perdido, hasta el 50% del PV Max. Ya no se acumula al final de la batalla. Tiempo de reutilización de 3 turnos.\n\nErosión escarlata: Después de usar el Horno Carmesí, inflige Corrosión a todos los enemigos igual al 1% de su PV Max. Cuanto más Horno Carmesí se consuma, más fuerte será el efecto de Corrosión, hasta +100%. Inflige un efecto de Corrosión 5× contra enemigos \"Cáscara vacía\".\n\nAl inicio de la exploración, PV Max +10%, Amplificación de Daño del equipo +50%, y todos los Cuerpos Despertados obtienen 20 Acumulaciones de \"Fiesta de Propagación\" En el inicio del turno. Si el equipo está compuesto únicamente por Cuerpos Despertados de Carne y sangre o del Caos, la Amplificación de Daño otorgada por este efecto se duplica.\nLa Maestría del Reino se convierte en \"Maestría de Carne de cría\": Cada punto de Maestría del Reino aumenta las Acumulaciones de \"Fiesta de Propagación\" obtenidas de \"Carne de cría\" en un 0,05%.\n\nSi el equipo está compuesto únicamente por Cuerpos Despertados de Carne y sangre o del Caos, el efecto de \"Maestría de Carne de cría\" se duplica."
  },
  AwakerTalent_145718_TalentName_1 = {
    Text = "Carne de cría"
  },
  AwakerTalent_146937_TalentDesc_1 = {
    Text = "Cuando Lotan: Cetarconte está en el equipo, el Reino del Caos se reforja en Primordio: Caos.\n\nAfluencia Primordial: La Llave Plateada base aumenta a 2000, la Amplificación de Daño del equipo aumenta en un 50%, y el ATQ y la DEF de todos los Despertados aumentan en un 10%. Si el equipo está compuesto únicamente por Cuerpos de despertar del caos, el bono de Amplificación de Daño de este efecto se duplica. Al inicio de la batalla, obtén 2000 de Llave Plateada.\n\nLlaves Confluentes: Los Niveles de carga de la llave de plata de todos los Despertados se establecen en el promedio del equipo. Los Despertados ya no obtienen Llave Plateada de la Aritmética consumida; en cambio, la primera Tarjeta de comando jugada por cada Despertado por turno otorga Llave Plateada igual a (su Regeneración de Llave Plateada × 3) + 100.\n\nReino Indivisible: Ya no activa los efectos de Reino Puro, Doble Maestría del Reino o Doble Amplificación de Daño de otros Reinos.\n\nEco Primordial: Las Cartas de Despertar obtienen Preparar 1; la Posse equipada actualmente se desencadena automáticamente la primera vez que se juega cada turno.\n\nFragmentos de Memoria: La Posse es reemplazada por Primordio: Recurrencia Dual y Primordio: Revelación Tríada, y la Posse portada en sí ya no puede ser desencadenada.\n\n-Primordio: Recurrencia Dual: Descubre 3 Posses de las que están en mano, luego elige 1 para desencadenar dos veces.\n-Primordio: Revelación Tríada: Descubre 3 conjuntos de Posses de las que están en mano, cada conjunto contiene 3 Posses diferentes. Elige un conjunto para desencadenar cada Posse dentro de él una vez, en secuencia.\nLas Posses incluidas en Primordio: Recurrencia Dual y Primordio: Revelación Tríada se extraen de los ocho tipos de Memoria Primordial.\nPrimordio: Recurrencia Dual y Primordio: Revelación Tríada cuentan cada uno como desencadenar solo 1 Posse. Cuando sus efectos se activarían varias veces, solo la primera Posse en surtir efecto es válida.\n\nMaestría del Primordio: Caos: La Maestría del Reino se convierte en Maestría del Primordio: Caos. Cada punto de Maestría del Primordio: Caos aumenta la Potencia de Posse en un 0,05%. Cada punto de Potencia de Posse aumenta el Veneno Fijo, el Contrataque Fijo, la STR Fija, las Cenizas Ancestrales Fijas en un 2%, y el Escudo del personaje Fijo, la Recuperación de PV Fija, la ganancia de STR▼ y Daño de tentáculos Fijos, la Probabilidad de Crítico, el Daño Crítico, la Amplificación de Daño, la Maestría del Reino, la Generación de Alienación, la Fusión Embrionaria y la Generación de Llave Plateada en un 1%."
  },
  AwakerTalent_146937_TalentName_1 = {
    Text = "Aliento Primigenio"
  },
  AwakerTalent_147414_TalentDesc_1 = {
