  AwakerTalent_44845_TalentDesc_1 = {
    Text = "·Por cada 1% de resistencia a la muerte proporcionada por Lily, su Rueda del destino y Pactos equipados, el escudo base de \"Pantano Prohibido\" y \"DEF básica\" aumenta en un 0.25%, y la acumulación y el límite de Paciencia en la batalla contra el Líder se incrementan en un 0.25%.\n·Cuando Lily está en el equipo, al perder 1 punto de vida, obtiene 1 capa de Paciencia, y el límite de acumulación de Paciencia es igual a su PV Max."
