  },
  AwakerTalent_46446_TalentDesc_1 = {
    Text = "·Ramona obtiene 2.5 puntos adicionales de regeneración de llave de plata. Cada nivel de tasa de sincronización le otorga a Ramona 0.5 puntos adicionales de regeneración de llave de plata. \n·Por cada punto de nivel de carga de la llave de plata, el daño básico de \"Espada de la Reina\" aumenta en un 1%, y al jugarlo, obtiene 0.75 de maestría temporal de dominio."
  },
  AwakerTalent_46446_TalentName_1 = {
    Text = "Resonancia del Corazón y la Plata"
  },
  AwakerTalent_46487_TalentDesc_1 = {
    Text = "·Ramona: Bucle obtiene 2.5 puntos adicionales de regeneración de llave plateada. Cada nivel de tasa de sincronización otorga a Ramona: Bucle 0.5 puntos adicionales de regeneración de llave plateada. \n·Por cada punto de nivel de carga de la llave de plata, el efecto de bucle de \"Golpe básico\" hace que Ramona: Bucle obtenga un 0.2% de probabilidad de crítico, y el efecto de bucle de \"DEF básica\" hace que Ramona: Bucle obtenga 0.2 puntos de alienación."
  },
  AwakerTalent_46487_TalentName_1 = {
    Text = "Resonancia del Corazón y la Plata"
  },
  AwakerTalent_49872_TalentDesc_1 = {
    Text = "·Por cada punto de maestría en dominios que posea Nautila, el daño de contraataque causado por \"Preparados y Listos\" aumenta un 0.25%."
  },
  AwakerTalent_49872_TalentName_1 = {
    Text = "mantenimiento"
  },
  AwakerTalent_49873_TalentDesc_1 = {
