  },
  AwakerTalent_51744_TalentDesc_1 = {
    Text = "Al comenzar la batalla, añade 1 \"Obsesión\" a tu mano.\nEl \"Golpe Básico\" de Miryam recibe una bonificación del 50% en Daño de tentáculos.\nPor cada 1% de Daño Crítico proporcionado por Miryam y su Rueda del destino y Pacto equipados, aumenta en un 0.2% la generación de FUE de Exaltar, el Daño de tentáculos, la Alienación, y la aplicación/activación de Veneno."
  },
  AwakerTalent_51744_TalentName_1 = {
    Text = "Piedad Inextinguible"
  },
  AwakerTalent_52071_TalentDesc_1 = {
    Text = "·Por cada nivel de recarga de locura proporcionado por Tulu mismo, su rueda de destino y sus pactos, \"Golpe básico\" recibe un 5% de bonificación en daño de tentáculo y fuerza, y \"Órdenes del abismo\" recibe un 15% de bonificación en daño de tentáculo y fuerza."
  },
  AwakerTalent_52071_TalentName_1 = {
    Text = "Poder del Rey Dios"
  },
  AwakerTalent_52086_TalentDesc_1 = {
    Text = "Por cada 1% de resistencia a la muerte proporcionada por Shan, su Rueda del Destino y pactos equipados, la locura obtenida por \"golpe básico\" y \"defensa básica\" aumenta 0.03 puntos, y \"El arte perdido\" recibe adicionalmente un 0.15% de bono en tasa crítica y daño crítico."
  },
  AwakerTalent_52086_TalentName_1 = {
    Text = "Inspiración de la muerte"
  },
  AwakerTalent_54047_TalentDesc_1 = {
