  AwakerTalent_54158_TalentDesc_1 = {
    Text = "·Por cada 1% de tasa crítica que posea Sorel, su Rueda del Destino y sus Pactos equipados, la locura obtenida por la \"defensa base\" aumenta en 0.2."
  },
  AwakerTalent_54158_TalentName_1 = {
    Text = "Guardián de la Ostentación"
  },
  AwakerTalent_55109_TalentDesc_1 = {
    Text = "·Por cada 1% de tasa crítica proporcionada por el cuerpo, la rueda del destino y los pactos de Jenkin, el daño base de \"golpe básico\" y \"¡Marrón, ataca!\" aumenta en un 2%."
  },
  AwakerTalent_55109_TalentName_1 = {
    Text = "Unidos contra el enemigo"
  },
  AwakerTalent_55176_TalentDesc_1 = {
    Text = "·Por cada punto de nivel de recarga de llave de plata proporcionado por el cuerpo del despertador Erika, su rueda del destino y sus pactos, \"Explosión electromagnética\" otorga a Erika un 0.5% adicional de tasa crítica temporal y daño crítico."
  },
  AwakerTalent_55176_TalentName_1 = {
    Text = "Fuente de energía externa"
  },
  AwakerTalent_55202_TalentDesc_1 = {
    Text = "·Al comenzar el turno, obtén 1 capa de Onirismo. \n ·Cada vez que consumas 1 capa de Onirismo, aumenta en un 5% el poder de ataque de los Contrataques obtenidos por el Guardián de lo perdido y la Necrópolis de los sueños en esta batalla. \n ·Por cada 1% de Amplificación de Daño proporcionada por el Despertado de Wanda, la Necrópolis de los sueños obtiene un aumento del 0.75% en los Contrataques."
  },
  AwakerTalent_55202_TalentName_1 = {
    Text = "Revelación"
  },
  AwakerTalent_55367_TalentDesc_1 = {
    Text = "·Por cada 1 punto de maestría en dominios proporcionado por el propio despertador Casiah, la rueda del destino o los pactos, \"Carnaval Mágico\" aumenta en un 0.2% el daño base de todas las cartas de Casiah."
  },
  AwakerTalent_55367_TalentName_1 = {
    Text = "Maestro de magia"
  },
  AwakerTalent_55507_TalentDesc_1 = {
    Text = "·Por cada 1% de probabilidad de caída del sigilo negro proporcionado por el cuerpo, la rueda del destino y los pactos de Tintura, \"Aurora iridiscente\" obtiene un 0.15% adicional de tasa crítica temporal."
  },
  AwakerTalent_55507_TalentName_1 = {
    Text = "Viajero planetario"
  },
  AwakerTalent_55837_TalentDesc_1 = {
    Text = "·El \"Golpe básico\" y la \"DEF básica\" de Horla también se consideran un poema. Cuando el poema se impulsa, cambia a diferentes emociones, que pueden afectar directamente el efecto de este poema. Estar en diferentes emociones traerá diferentes efectos de equipo continuos. \n·Por cada 1% de Resistencia a la muerte que tenga Horla, el bono de este efecto aumenta en un 0.1% del valor inicial."
  },
  AwakerTalent_55837_TalentName_1 = {
    Text = "Pluma amorosa"
  },
  AwakerTalent_56174_TalentDesc_1 = {
    Text = "·Por cada 1% de atributo de aumento de daño que posea Faros, el escudo generado por \"La ciudad antigua perdida\" aumenta un 0.4%."
  },
  AwakerTalent_56174_TalentName_1 = {
    Text = "Obsesión por el retorno a la patria"
  },
  AwakerTalent_56175_TalentDesc_1 = {
    Text = "·Por cada 1% de caída del sigilo negro que posea Kaix, \"Golpe base\" recibirá un 1% de bonificación de contraataque."
  },
  AwakerTalent_56175_TalentName_1 = {
    Text = "Púas rebeldes"
  },
  AwakerTalent_56223_TalentDesc_1 = {
    Text = "·Celeste activa una carta de comando para desencadenar 1 tentáculo que ataque a los enemigos; por cada 1 punto de maestría de reino de Celeste, la rueda y el pacto, esta activación causa un daño adicional de 0.5% de tentáculo."
  },
  AwakerTalent_56223_TalentName_1 = {
    Text = "Corneta de navegación lejana"
  },
  AwakerTalent_57336_TalentDesc_1 = {
    Text = "·Por cada 1% de probabilidad de caída de sellos negros que posea Salvador, el límite máximo del Horno Carmesí aumentará en 0.15% de su vida máxima."
  },
  AwakerTalent_57336_TalentName_1 = {
    Text = "Lugar de inicio"
  },
  AwakerTalent_57408_TalentDesc_1 = {
    Text = "Por cada 1% de Recompensa de Sello Negro que tengan Agrippa y su Rueda del destino y Pacto equipados, el Escudo Base de \"Bendición pálida\" +0.5%, y el Veneno base +1%."
  },
  AwakerTalent_57408_TalentName_1 = {
    Text = "Marca de pacto"
  },
  AwakerTalent_57419_TalentDesc_1 = {
    Text = "·Por cada 1% de Resistencia a la muerte que posea Faint, el Contrataque obtenido por \"Cuna de las estrellas\" y \"Luz estelar sin límites\" aumenta un 0.2%, y el límite de Resistencia a la muerte de \"Cuna de las estrellas\" +2%."
  },
  AwakerTalent_57419_TalentName_1 = {
    Text = "Cuna Secundaria"
  },
  AwakerTalent_57567_TalentDesc_1 = {
    Text = "·Por cada 1% de efecto fuerte de daño que posea Helot, \"Supervivencia en circunstancias críticas\" aumenta el daño causado por Helot en este turno un 0,3%."
  },
  AwakerTalent_57567_TalentName_1 = {
    Text = "Cicatriz de dolor"
  },
  AwakerTalent_58448_TalentDesc_1 = {
    Text = "Ryker obtiene 5 Marcas negras al matar a un enemigo. Por cada 1% de Recompensa de Sello Negro que tenga Ryker, la cantidad obtenida +1%, hasta 5 veces por exploración.\nDespués de obtener 75/150/300 Marcas negras a través de la batalla, el límite de reliquias +1, y al final de la batalla elige un <C05_zaowu:\"Legado del Caos\"> para añadir a la lista de reliquias."
  },
  AwakerTalent_58448_TalentName_1 = {
    Text = "El ganador se lo lleva todo"
  },
  AwakerTalent_70306_TalentDesc_1 = {
    Text = "·Durante la batalla contra el jefe, al inicio del turno y después de que \"Doll Fusión\" libere su exaltación de locura, obtén 1 capa de \"Fin\". \"Fin\" puede tener un máximo de 10 capas; al alcanzar las 10 capas, coloca 1 carta \"Fin de la Ilusión\" en tu mano."
  },
  AwakerTalent_70306_TalentName_1 = {
    Text = "Camino de la Aniquilación"
  },
  AwakerTalent_74099_TalentDesc_1 = {
    Text = "·Este talento solo es efectivo en las misiones del \"Capítulo de las Estrellas\".\n·La constitución, ataque y defensa de este Despertado aumentan un [Arg1]%, y después de jugar por primera vez una carta de despertar de gnosis, obtiene [Arg2] puntos de Llave Plateada.\n·Cada tentáculo que ataque aumentará el daño temporal de tentáculos en un [Arg3]% del ATQ de Tulu, activándose un máximo de [Arg4] veces por turno.\n·Cuando hay 1/2/3 otros Cuerpo Despertado \"Lemurianos\" en el equipo, todos los enemigos reciben un 10%/25%/50% más de Daño de tentáculos."
  },
