    Text = "·Este talento solo es efectivo en las misiones del \"Capítulo de las Estrellas\".\n·La constitución, ataque y defensa de este Despertado aumentan un [Arg1]%, y después de jugar por primera vez una carta de despertar de gnosis, obtiene [Arg2] puntos de Llave Plateada.\n·Cada tentáculo que ataque aumentará el daño temporal de tentáculos en un [Arg3]% del ATQ de Tulu, activándose un máximo de [Arg4] veces por turno.\n·Cuando hay 1/2/3 otros Cuerpo Despertado \"Lemurianos\" en el equipo, todos los enemigos reciben un 10%/25%/50% más de Daño de tentáculos."
  },
