  AwakerTalent_74101_TalentDesc_1 = {
    Text = "·Este talento solo es efectivo en los niveles del \"Capítulo de las Estrellas\".\n·El CON, ATQ y DEF de este Cuerpo Despertado aumentan un [Arg1] %, y tras Activar por primera vez, obtiene [Arg2] puntos de Llave Plateada.\n·La Marca negra que Ryker obtiene por sí mismo aumenta un [Arg4]%, y la Probabilidad de Crítico aumenta un [Arg3]%. Si se obtienen al menos 400 Marcas negras durante el combate, al inicio de la batalla se mejora 1 \"Legado del Caos\"."
