  AwakerTalent_74105_TalentDesc_1 = {
    Text = "·Este talento solo es efectivo en los niveles del \"Capítulo de las Estrellas\".\n·El CON, ATQ y DEF de este Cuerpo Despertado aumentan un [Arg1] %, y tras Activar por primera vez, obtiene [Arg2] puntos de Llave Plateada.\n·Por cada \"División de glándulas\" consumida por \"Océano clamoroso\", el Daño posterior causado por Aurita en esta batalla aumenta un [Arg3]% del ATQ. En Líder Batalla, si \"Océano clamoroso\" ha consumido al menos 20 \"División de glándulas\", el número de veces que \"División de glándulas\" causa Daño al jugarse o ser consumida +1. Las primeras [Arg4] \"División de glándulas\" jugadas cada turno no añadirán \"Armonía Aritmética\"."
  },
