  AwakerTalent_74108_TalentDesc_1 = {
    Text = "·Este talento solo es efectivo en los niveles del \"Capítulo de las Estrellas\".\n·El CON, ATQ y DEF de este Cuerpo Despertado aumentan un [Arg1] %, y tras Activar por primera vez, obtiene [Arg2] puntos de Llave Plateada.\n·El Blindaje causado por Ogier aumenta un [Arg3]%, la Fortaleza causada aumenta un [Arg4]%. Cada vez que se libera Exaltar, el Blindaje causado por Ogier en esta batalla aumenta adicionalmente un 1% de la DEF."
  },
