    Text = "· Este talento solo es efectivo en niveles de \"Reinado Astral\".\n· La constitución, ataque y defensa del despertador aumentan en [Arg1] %, y este despertador gana [Arg2] puntos de energía de destello plateado después de la primera iluminación.\n· Al comienzo de la batalla, si hay enemigos \"Bestia\", el poder de Casiah en esta batalla aumenta en [Arg3] %. \"Poof\" activa el efecto de réplico de barajar la pila de cartas robadas en su primera liberación cada turno."
  },
