  AwakerTalent_74112_TalentDesc_1 = {
    Text = "·Este talento solo es efectivo en los niveles del \"Capítulo de las Estrellas\".\n·El CON, ATQ y DEF de este Cuerpo Despertado aumentan un [Arg1] %, y tras Activar por primera vez, obtiene [Arg2] puntos de Llave Plateada.\n·Cuando Sanga causa Blindaje, obtiene Daño de tentáculos equivalente al [Arg3]% del valor del Blindaje. Cuando Sanga libera Exaltar, disfruta adicionalmente de un [Arg4]% de Bonificación de daño de tentáculos."
  },
