  AwakerTalent_74113_TalentDesc_1 = {
    Text = "Este talento solo es efectivo en las fases \"Reinado Astral\".\nCON, ATQ y DEF de este Despertado +[Arg1]%, y obtiene [Arg2] Keyflare en su primer Despertar.\n\"Látigo de la locura\" obtiene Retener y Preparar. Los enemigos con intención de ataque reciben un [Arg3]% más de Daño Activo de Pandia, que aumenta un +5% por instancia de ataque adicional, hasta un 20%."
  },
