  AwakerTalent_74114_TalentDesc_1 = {
    Text = "·Este talento solo es efectivo en las misiones del \"Capítulo de las Estrellas\".\n·La constitución, ataque y defensa de este Despertado aumentan un [Arg1] %, y después de jugar por primera vez una carta de despertar de gnosis, obtiene [Arg2] puntos de llave plateada.\n·Aigis obtiene energía de llave plateada equivalente al [Arg3]% de regeneración de llave plateada después de jugar la primera carta de comando en cada turno."
  },
