    Text = "·Este talento solo es efectivo en las misiones del \"Capítulo de las Estrellas\". \n·La constitución, ataque y defensa de este Despertado aumentan un [Arg1]%, y después de jugar por primera vez una carta de activar, obtiene [Arg2] puntos de llave plateada. \n·Las primeras [Arg3] cartas de \"¡Grito, Sangre!\" jugadas en cada turno no añadirán \"Armonía Aritmética\". El daño básico causado por Uvhash aumenta en un [Arg4]%, y si su vida está por debajo del 25%, el efecto se duplica."
