  AwakerTalent_74116_TalentDesc_1 = {
    Text = "·Este talento solo es efectivo en las misiones del \"Capítulo de las Estrellas\".\n·La constitución, ataque y defensa de este Despertado aumentan un [Arg1] %, y después de jugar por primera vez una carta de despertar de Gnosis, obtiene [Arg2] puntos de Llave Plateada.\n·Thais gana [Arg3]% de energía-s de llave de plata al devorar un Embrión, y el efecto de devorar un \"Vástago de la Pureza\" se duplica."
  },
  AwakerTalent_74116_TalentDesc_10 = {
    Text = "·Este talento solo es efectivo en las misiones del \"Capítulo de las Estrellas\".\n·La constitución, ataque y defensa de este Despertado aumentan un [Arg1] %, y después de jugar por primera vez una carta de despertar de Gnosis, obtiene [Arg2] puntos de Llave Plateada.\n·Thais obtiene energía-s de llave de plata equivalente al [Arg3]% de la Regeneración de Llave Plateada al devorar un Embrión, y el efecto al devorar un \"Vástago de la Pureza\" se duplica."
