  AwakerTalent_74117_TalentDesc_1 = {
    Text = "·Este talento solo tiene efecto en las etapas de \"Reinado Astral\".\n·El <awakener>'s <con>, <attack>, y <defence> aumentan en [Arg1]%, y al jugar por primera vez el <gnosis> <rouse>, gana [Arg2] puntos de <keyflare>.\n·Después de desatar \"Aniquilación,\" <Winkle> gana [Arg3] puntos de <aliemus>, con un tiempo de recarga de 3 turnos."
  },
