  AwakerTalent_74118_TalentDesc_1 = {
    Text = "·Este talento es efectivo solo en las etapas de \"Reinado Astral\".\n·La con, atk y def de este Despertador aumentan en [Arg1]%, y al jugar inicialmente Gnosis Despertar, gana energía de Llave de Plata [Arg2].\n·El daño base de Goliat aumenta en [Arg3]%, y \"Dominio de la hoja\" aumenta temporalmente el daño final de Goliat en [Arg4]%. \n·Cuando el equipo contiene 1/2/3 otros Despertadores de \"Lemuria\", los efectos de ganancia de fuerza de todos los Despertadores se mejoran adicionalmente en 6%/15%/30%."
  },
