  AwakerTalent_74120_TalentDesc_1 = {
    Text = "·Este talento solo es efectivo en las misiones del \"Capítulo de las Estrellas\".\n·La constitución, ataque y defensa de este Despertado aumentan un [Arg1]%, y después de jugar por primera vez una carta de Despertar, obtiene [Arg2] puntos de Keyflare.\n·El daño básico causado por la tarjeta de comando de Lotan aumenta un [Arg3]%. Cada vez que Lotan causa daño, el daño Activo de Lotan en este turno aumenta un 2%, hasta un máximo de [Arg4]%."
