  AwakerTalent_74122_TalentDesc_1 = {
    Text = "·Este talento solo es efectivo en los niveles del \"Capítulo de las Estrellas\".\n·El CON, ATQ y DEF de este Cuerpo Despertado aumentan un [Arg1] %, y tras Activar por primera vez, obtiene [Arg2] puntos de Llave Plateada.\n·Tras jugar \"Melodía distante\", el Daño causado por todos los enemigos \"Humanoides\" se reduce Temporalmente un [Arg4]%, sin acumulación. \"Réquiem\" obtiene [Arg3] puntos de Aliemus, con 1 adicional por cada Estado negativo disipado."
  },
