  AwakerTalent_74124_TalentDesc_1 = {
    Text = "·Este talento solo es efectivo en las misiones del \"Capítulo de las Estrellas\".\n·La constitución, ataque y defensa de este Despertado aumentan un [Arg1]%, y después de jugar por primera vez una carta de despertar de Gnosis, obtiene [Arg2] puntos de Llave Plateada.\n·La locura de Doll y el efecto de curación causados por la exaltación aumentan un [Arg3]%, y por cada otro Despertado del reino del \"Caos\" en el equipo, este efecto aumenta en un [Arg4]%."
  },
