    Text = "· Este talento es efectivo solo en niveles de \"reinados astrales\".\n· El con, ataque y defensa de este despertador aumentan en [Arg1]% y gana [Arg2] destello clave al activar por primera vez \"despertar\".\n· Los efectos de ganancia de str de Leigh aumentan en [Arg4]%, y después de jugar la \"carta de comando\" de Leigh, gana [Arg3]% del atk de Leigh como str, el efecto puede aumentar hasta un 200% según los hp perdidos actuales, y se puede activar hasta 3 veces por turno."
