  AwakerTalent_74127_TalentDesc_1 = {
    Text = "·Este talento solo es efectivo en los niveles del \"Capítulo de las Estrellas\".\n·El CON, ATQ y DEF de este Cuerpo Despertado aumentan un [Arg1] %, y tras Activar por primera vez, obtiene [Arg2] puntos de Llave Plateada.\n·Por cada \"Cocina maravillosa\" en la Mano, la Cicatrización de PV y el efecto de Blindaje causados aumentan un [Arg4]%, acumulable hasta 3 capas. Por cada vez que se juega \"Cocina maravillosa\", el Veneno causado por Karen en esta batalla aumenta un [Arg3]%, acumulable hasta 20 capas."
  },
