  AwakerTalent_74129_TalentDesc_1 = {
    Text = "·Este talento solo es efectivo en los niveles del \"Capítulo de las Estrellas\".\n·El CON, ATQ y DEF de este Cuerpo Despertado aumentan un [Arg1] %, y tras Activar por primera vez, obtiene [Arg2] puntos de Llave Plateada.\n·El Daño Final del \"golpear\" de Lily aumenta un [Arg3]%, y se duplica en Líder Batalla. Tras recibir un ataque de un enemigo \"Ultra\", obtiene un efecto de Cicatrización con Latencia equivalente al [Arg4]% del PV perdido en ese ataque. \"Huelga para proteger\" disfruta de un [Arg5]% de bonificación de Amplificación de Daño junto con el efecto de Daño aumentado de \"Paciencia\"."
  },
