  AwakerTalent_74130_TalentDesc_1 = {
    Text = "· Este talento solo es efectivo en niveles de \"Astral Reign\".\n· La constitución, ataque y defensa del despertador aumentan en un [Arg1] %, y este despertador gana [Arg2] puntos de energía de clave de plata después de la primera iluminación.\n· Después de que Sorel \"devora\", gana fuerza temporal de [Arg3] % de su poder de ataque, puede desencadenarse un máximo de 5 veces por turno."
