  AwakerTalent_74132_TalentDesc_1 = {
    Text = "·Este talento solo es efectivo en los niveles del \"Capítulo de las Estrellas\".\n·El CON, ATQ y DEF de este Cuerpo Despertado aumentan un [Arg1] %, y tras Activar por primera vez, obtiene [Arg2] puntos de Llave Plateada.\n·El Veneno causado por Faros aumenta un [Arg3]%. Al final del turno, \"Ciudad perdida de Lemuria\" ordena a todos los Tentáculos atacar 1 vez, pero estos ataques solo causan un [Arg4]% del Daño.\n·Cuando hay 1/2/3 otros Cuerpos Despertados de \"Lemuria\" en el equipo, Amplificación de Daño +20%/50%/100%."
