  AwakerTalent_74134_TalentDesc_1 = {
    Text = "·Este talento solo es efectivo en las misiones del \"Capítulo de las Estrellas\".\n·La constitución, ataque y defensa de este Despertado aumentan un [Arg1]%, y después de jugar por primera vez una carta de activar, obtiene [Arg2] puntos de llave plateada.\n·El daño final que Helot causa a los enemigos en el \"Campo de Nieve\" aumenta en un [Arg3]%. Si en este turno Helot ha consumido el \"Embrión\", el próximo daño que cause en este turno tendrá un daño crítico + [Arg4]%."
  },
