  AwakerTalent_74135_TalentDesc_1 = {
    Text = "·Este talento solo tiene efecto en las etapas del \"Capítulo Stella\".\n·La vitalidad, ataque y defensa del Despertador aumentan en [Arg1] %, y el Despertador gana [Arg2] puntos de Energía-s después de su primera Despertar de Gnosis.\n·Al inicio de la batalla contra el jefe, gana resistencia a la muerte igual al atributo de resistencia a la muerte de Horla [Arg3]%. Después de cada activación de la resistencia a la muerte, el efecto del \"Capítulo Caprichoso\" correspondiente aumenta en [Arg4]% hasta el final del turno."
  },
