  AwakerTalent_74136_TalentDesc_1 = {
    Text = "·Este talento solo es efectivo en las misiones del \"Capítulo de las Estrellas\".\n·La constitución, ataque y defensa de este Despertado aumentan un [Arg1]%, y después de jugar por primera vez una carta de despertar de Gnosis, obtiene [Arg2] puntos de Llave Plateada.\n·Al comenzar la batalla, coloca 1 carta adicional de \"Llamas corruptas\" con el efecto \"Consumo\" en tu mano, y aumenta el daño básico de \"Llamas verdes\" y sus cartas derivadas en un [Arg3]%."
