  AwakerTalent_74137_TalentDesc_1 = {
    Text = "·Este talento solo es efectivo en los niveles del \"Capítulo de las Estrellas\".\n·El CON, ATQ y DEF de este Cuerpo Despertado aumentan un [Arg1] %, y tras Activar por primera vez, obtiene [Arg2] puntos de Llave Plateada.\n·Al Refrescar \"Ruinas Cenicientas\", la probabilidad de que aparezca un descuento aumenta un [Arg3]%, y el porcentaje de descuento aumenta un [Arg4]%.\n·El Daño básico de \"Devastador de calaveras\" aumenta un [Arg5] %, calculado de forma independiente al aumento de Daño básico por Matar."
  },
