  AwakerTalent_74138_TalentDesc_1 = {
    Text = "·Este talento solo es efectivo en la etapa de \"reinado astral\".\n·La constitución, ataque y defensa del despertador aumentan en [Arg1]%, y al usar despertar por primera vez, el despertador gana [Arg2] puntos de energía de la llave de plata.\n·Caecus juega la primera carta de comando cada turno para restaurar [Arg3]% de los puntos de vida de su constitución. Los ataques de tentáculos y los efectos de contraataque de la \"línea de sangre de la herejía\" además infligen [Arg4]% de daño."
  },
