  AwakerTalent_74139_TalentDesc_1 = {
    Text = "·Este talento solo es efectivo en las misiones del \"Capítulo Estelar\". \n·La CON, ATQ y DEF de este Cuerpo Despertado +[Arg1]%, y obtiene [Arg2] Keyflare tras su primer Despertar.\n·La generación de Contador de Nautila +[Arg3]%. Antes de desatar \"Listos y preparados\", obtiene Contador Temporal equivalente al [Arg4]% del Contador Permanente."
