  AwakerTalent_78618_TalentDesc_1 = {
    Text = "·Este talento solo se activa en la etapa \"Reinado Astral\".\n·La constitución, ataque y defensa de este Despertador aumentan en [Arg1] %, y al activar por primera vez el Despertar de Gnosis, el Despertador gana [Arg2] puntos de energía Llave de Plata.\n·El efecto de daño base aplicado por \"Redención del Agonía\" aumenta el poder de ataque de Pollux en [Arg3] %.\n·Cada acumulación de 50 capas de \"Marca de Pecado\" colocará un \"Corazón Sagrado\" en la mano.\n·Cuando \"Marca de Pecado\" alcance 100 capas, roba una de tus propias \"Carta de Habilidad\" después del tercer consumo.\n·Al causar daño, los efectos de \"Marca de Pecado\" en enemigos de la \"Iglesia de los Portadores de Luz\" se duplican."
  },
