  AwakerTalent_78620_TalentDesc_1 = {
    Text = "Este talento solo es efectivo en las fases \"Reinado Astral\".\nCON, ATQ y DEF de este Despertado +[Arg1]%, y obtiene [Arg2] Keyflare en su primer Despertar.\nAl inicio del combate, todos los enemigos reciben un [Arg3]% más de Daño de tentáculos. Este efecto se duplica contra los enemigos \"Aequor\". El Daño Activo infligido por \"Retribución del rayo\" a los enemigos \"Aequor\" +[Arg4]%."
  },
