  AwakerTalent_78622_TalentDesc_1 = {
    Text = "·Este talento solo entra en efecto en las etapas del \"Capítulo Stella\".\n·La vitalidad, ataque y defensa del Despertador aumentan en [Arg1] %, y el Despertador gana [Arg2] puntos de Energía-s después de su primer Despertar de Gnosis.\n·El efecto de mejora de \"Llama Viviente\" aumenta en [Arg3]%, al comienzo del turno y antes de la fase de descarte, borra todo \"Quemadura\" de la mano; por cada capa, Kaitigra gana 1 capa de \"Llama Explosiva\"."
  },
