  AwakerTalent_78623_TalentDesc_1 = {
    Text = "Este talento solo es efectivo en las fases \"Reinado Astral\".\nCON, ATQ y DEF de este Despertado +[Arg1]%, y obtiene [Arg2] Keyflare en su primer Despertar.\nProbabilidad de Crítico y Daño Crítico de Exaltar de Caraboo +[Arg3]%. \"Saciedad\" aumenta el PV Max en un [Arg5]%.\nEn el terreno \"Campos de Hielo\": el Coste de Aritmética de \"Hechizo Nevado\" -1; el número de impactos de daño +1; inflige daño a & aplica Síntoma: Debilidad a todos los enemigos."
