  AwakerTalent_78624_TalentDesc_1 = {
    Text = "· Este talento solo es efectivo en niveles de \"Reinado Astral\".\n· La constitución, ataque y defensa del despertador aumentan en [Arg1] %, y este despertador gana [Arg2] puntos de energía de destello plateado después de la primera iluminación.\n· Jugar \"Pluma de Ónix\" no añade \"Armonía Aritmética\", y la corrosión infligida por \"Plumas de Purificación\" aumenta el poder de ataque de Castor en [Arg3] %. \n· La corrosión que Castor inflige a los enemigos de \"Iglesia de los Portadores de Luz\" aumenta en [Arg4] %."
  },
