  AwakerTalent_78636_TalentDesc_1 = {
    Text = "·Este talento solo es efectivo en las misiones del \"Capítulo Estelar\". \n·La constitución, ataque y defensa de este Despertado aumentan un [Arg1]%, y después de jugar por primera vez una carta de despertar de gnosis, obtiene [Arg2] puntos de energía-s de llave de plata."
