  AwakerTalent_78642_TalentDesc_1 = {
    Text = "·Este talento solo es efectivo en el nivel \"Capítulo de las Estrellas\".\n·La CON, el Ataque y la Defensa de este Despertado aumentan en [Arg1] %, y el Despertado obtiene [Arg2] puntos de Llave Plateada después de activar por primera vez Gnosis. \n·El \"Corte del destino\" de Arachne aumenta en [Arg3] %, y el \"Corte del destino\" contra enemigos Mutantes se duplica."
