  AwakerTalent_78645_TalentDesc_1 = {
    Text = "·Este talento solo se activa en la etapa \"Reinado Astral\".\n·La constitución, ataque y defensa de este Despertador aumentan en [Arg1] %, y al activar por primera vez el Despertar de Gnosis, el Despertador gana [Arg2] puntos de energía Llave de Plata.\n·La fuerza ganada por todos los Despertadores aumenta en [Arg3] %.\n·Clementine aplica un efecto de sangrado causando [Arg4] % de daño a los objetivos al atacar a enemigos \"insectoides\". Cuando Clementine genera un escudo o recupera vida por primera vez cada ronda, los enemigos \"insectoides\" pierden temporalmente [Arg5] % de su defensa."
  },
