  AwakerTalent_78911_TalentDesc_1 = {
    Text = "·Este talento solo es efectivo en las misiones del \"Capítulo Estelar\".\n·CON, ATQ y DEF de este Cuerpo Despertado +[Arg1]%, y obtiene [Arg2] Keyflare tras su primer Despertar.\n·Cada vez que Murphy: Falso Engendro inflige Daño, aplica Acumulaciones de \"Ritual de sacrificio\" equivalentes al [Arg3]% del Daño infligido sobre el objetivo. El efecto de aumento de Acumulaciones de \"Ritual de nacimiento\" del estado \"Pacto del destino\" se duplica.\n·Cuando hay 1/2/3 otros Cuerpos Despertados \"Lemurianos\" en el equipo: PV Max +6%/15%/30%; se obtiene Escudo del personaje equivalente al 50%/125%/250% de la DEF de Murphy: Falso Engendro después de que cualquier Cuerpo Despertado \"Lemuriano\" use Exaltar. Limitado a una vez por turno; no se beneficia de bonificaciones de generación de Escudo del personaje."
  },
