  AwakerTalent_79211_TalentDesc_1 = {
    Text = "·Las cartas de comando de Clementine obtienen 1 capa de \"empatía\" después de causar daño. \n·Por cada 1 punto de atributo de regeneración de llave plateada que proporcionen el Despertado de Clementine, la rueda del destino y el pacto, la probabilidad de crítico y el daño crítico aumentan en 0.35%. \n·Después de que comience el turno Ultra, elimina el \"trauma psicológico\" y la \"fijación fóbica\" de todos los enemigos. Por cada capa de \"trauma psicológico\" eliminada de todos los enemigos, obtienes 50 puntos de energía de llave plateada, y por cada capa de \"fijación fóbica\" eliminada de todos los enemigos, los demás Despertados obtienen 2 puntos de alienación."
  },
  AwakerTalent_79211_TalentName_1 = {
    Text = "Sentidos de la colmena"
  },
  AwakerTalent_79788_TalentDesc_1 = {
    Text = "·Este talento solo es efectivo en las misiones del \"Capítulo Estelar\". \n·La constitución, ataque y defensa de este Despertado aumentan un [Arg1]%, y después de jugar por primera vez una carta de despertar de gnosis, obtiene [Arg2] puntos de energía-s de llave de plata."
  },
