  AwakerTalent_89775_TalentDesc_1 = {
    Text = "Cada vez que Juegues por primera vez una carta de \"Pluma negra\" en cada turno, inflige \"Corrosión\" del 840% del ATQ de Castor al objetivo y obtén 10 de Aliemus.\nPor cada 1% de Amplificación de Daño que tenga Castor, aumenta en un 1% la cantidad Base de \"Corrosión\" infligida.\nAl finalizar la batalla, la \"Corrosión\" infligida por Castor en esta exploración aumenta permanentemente en un 20%.\nLa \"Corrosión\" infligida en Líder Batallas se duplica.\nDespués de infligir \"Corrosión\", el Daño de Castor aumenta en un 5% de la cantidad de \"Corrosión\" infligida en este turno.\nEl Daño infligido por Castor no elimina la \"Corrosión\"."
  },
